package com.jnapanam.sportszone.release1.controller;import com.jnapanam.sportszone.release1.service.Release1OperationsService;import java.util.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/release1/ops")public class Release1OperationsController{private final Release1OperationsService s;public Release1OperationsController(Release1OperationsService s){this.s=s;}
 @PostMapping("/support/{id}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public Map<String,Object> support(Authentication a,@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.support(uid(a),id,str(b,"action"),str(b,"details"),b.get("assigneeId")==null?null:UUID.fromString(str(b,"assigneeId")));}
 @GetMapping("/equipment-inventory")@PreAuthorize("hasAnyRole(\u0027SUPER_ADMIN\u0027,\u0027ADMIN\u0027,\u0027OPERATIONS\u0027)")public List<Map<String,Object>> inventory(){return s.inventory();}
 @PostMapping("/equipment-inventory")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','OPERATIONS')")public Map<String,Object> inventory(@RequestBody Map<String,Object>b){return s.inventory(b.get("facilityId")==null?null:UUID.fromString(str(b,"facilityId")),str(b,"equipmentName"),num(b,"totalQuantity"),Long.parseLong(String.valueOf(b.getOrDefault("depositPaise",0))));}
 @PostMapping("/memberships/{id}/family")@PreAuthorize("hasAnyRole(\u0027SUPER_ADMIN\u0027,\u0027ADMIN\u0027)")public Map<String,Object> family(@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.family(id,UUID.fromString(str(b,"dependentId")));}
 @PostMapping("/training/{id}/installments")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public Map<String,Object> installment(@PathVariable UUID id,@RequestBody Map<String,Object>b){return s.installment(id,num(b,"installmentNo"),Long.parseLong(str(b,"amountPaise")),str(b,"dueDate"));}
 @GetMapping("/tournaments/{id}/standings")public List<Map<String,Object>> standings(@PathVariable UUID id){return s.standings(id);}
 @PutMapping("/tournaments/{id}/standings/{team}")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN','ORGANIZER')")public Map<String,Object> standing(@PathVariable UUID id,@PathVariable UUID team,@RequestBody Map<String,Object>b){return s.standing(id,team,num(b,"played"),num(b,"won"),num(b,"drawn"),num(b,"lost"),num(b,"points"),num(b,"scoreFor"),num(b,"scoreAgainst"),Double.parseDouble(String.valueOf(b.getOrDefault("tieBreakValue",0))));}
 private static UUID uid(Authentication a){return UUID.fromString(a.getName());}private static String str(Map<String,Object>b,String k){Object v=b.get(k);return v==null?null:v.toString();}private static int num(Map<String,Object>b,String k){return Integer.parseInt(String.valueOf(b.getOrDefault(k,0)));}}
